use serde_json::{json,Value};
use std::{collections::HashMap,sync::Mutex,path::PathBuf,time::Duration};
use tauri::{Emitter,State,WebviewUrl,WebviewWindowBuilder};
struct Session{data:Value,files:Vec<PathBuf>,printing:bool}
#[derive(Default)]pub struct PdfExports{sessions:Mutex<HashMap<String,Session>>}
impl PdfExports{pub fn remove(&self,label:&str){self.sessions.lock().unwrap().remove(label);}}
fn shows(library:&crate::Library,data:&Value)->Result<Vec<Value>,String>{
 let mut result=Vec::new();for id in data["showIds"].as_array().ok_or("Select shows to export")?{let id=id.as_str().ok_or("Invalid show ID")?;let item=data["projectItems"].as_array().and_then(|items|items.iter().find(|item|item["id"]==id));if let Some(item)=item.filter(|item|item["type"].as_str().is_some_and(|kind|kind!="show")){
 let kind=item["type"].as_str().unwrap_or("");let name=item["name"].as_str().unwrap_or(id);if kind=="section"{result.push(json!({"id":id,"name":name,"type":kind,"color":item["color"],"notes":item["notes"],"data":item["data"],"meta":{},"settings":{"activeLayout":"default"},"slides":{},"layouts":{},"media":{}}));}else if ["image","video","audio"].contains(&kind){result.push(json!({"id":id,"name":name,"type":kind,"meta":{},"settings":{"activeLayout":"default"},"slides":{"slide1":{"items":[],"settings":{},"notes":""}},"layouts":{"default":{"id":"default","name":"Default","slides":[{"id":"slide1","background":id}]}},"media":{id:{"id":id,"path":id,"type":"media"}}}));}continue}
 let value=crate::load(library.show_path(id)?)?;let mut show=value[1].clone();if !show.is_object(){return Err("Invalid show for PDF export".into());}show["id"]=json!(id);result.push(show)}if result.is_empty(){return Err("No shows selected".into())}Ok(result)
}
#[tauri::command]
pub async fn pdf_export(app:tauri::AppHandle,caller:tauri::Webview,library:State<'_,crate::Library>,state:State<'_,PdfExports>,operation:String,data:Value)->Result<Value,String>{
 if caller.label()!=caller.window().label(){return Err("PDF export requires a FreeShow window".into());}
 if operation=="START"{if caller.label()!="main"{return Err("Start PDF export from the editor".into())}let mut data=data;data["shows"]=json!(shows(&library,&data)?);let label=format!("pdf-{}",uuid::Uuid::new_v4());state.sessions.lock().unwrap().insert(label.clone(),Session{data,files:Vec::new(),printing:false});let dimensions=if state.sessions.lock().unwrap()[&label].data["options"]["type"]=="media"{(1123.0,631.0)}else{(794.0,1123.0)};let window=WebviewWindowBuilder::new(&app,&label,WebviewUrl::App("index.html".into())).title("FreeShow PDF export").visible(false).focused(false).skip_taskbar(true).decorations(false).inner_size(dimensions.0,dimensions.1).build();if let Err(error)=window{state.remove(&label);return Err(error.to_string())}return Ok(json!({"started":true}));}
 let label=caller.label().to_owned();if !label.starts_with("pdf-")||!state.sessions.lock().unwrap().contains_key(&label){return Err("Unknown PDF export window".into())}
 if operation=="DATA"{return Ok(state.sessions.lock().unwrap()[&label].data.clone())}
 if operation=="DONE"{let session=state.sessions.lock().unwrap().remove(&label).unwrap();caller.window().close().map_err(|e|e.to_string())?;app.emit_to("main","freeshow-ipc",json!({"channel":"MAIN","msg":{"channel":"TOAST","data":"export.exported"}})).map_err(|e|e.to_string())?;return Ok(json!({"files":session.files}))}
 if operation!="PRINT"{return Err("Unknown PDF export operation".into())}
 {let mut sessions=state.sessions.lock().unwrap();let session=sessions.get_mut(&label).unwrap();if session.printing{return Err("PDF print already running".into())}session.printing=true;}
 let folder=library.root.join("Exports");let temporary=folder.join(format!(".freeshow-pdf-{}.pdf",uuid::Uuid::new_v4()));let printed=match std::fs::create_dir_all(&folder){Ok(())=>print(&caller,&temporary,data["options"]["type"]=="media").await,Err(error)=>Err(error.to_string())};
 let result=match printed{Ok(())=>{match std::fs::read(&temporary).map_err(|e|e.to_string()){Err(error)=>Err(error),Ok(bytes)=>if !bytes.starts_with(b"%PDF-"){Err("Export did not produce a valid PDF".into())}else{crate::library_services::save_export(&folder,data["name"].as_str().unwrap_or("Export"),"pdf",&bytes)}}},Err(error)=>Err(error)};let _=std::fs::remove_file(&temporary);
 if let Some(session)=state.sessions.lock().unwrap().get_mut(&label){session.printing=false;if let Ok(file)=&result{session.files.push(file.clone());}}
 match result{Ok(file)=>Ok(json!({"path":file})),Err(error)=>{state.remove(&label);let _=caller.window().close();app.emit_to("main","freeshow-ipc",json!({"channel":"MAIN","msg":{"channel":"ALERT","data":format!("PDF export failed: {error}")}})).map_err(|e|e.to_string())?;Err(error)}}
}
async fn print(view:&tauri::Webview,path:&std::path::Path,media:bool)->Result<(),String>{
 use windows::core::PCWSTR;use windows_core::Interface;use webview2_com::{PrintToPdfCompletedHandler,Microsoft::Web::WebView2::Win32::{ICoreWebView2_7,ICoreWebView2Environment6}};
 let (sender,receiver)=tokio::sync::oneshot::channel();let path=path.as_os_str().to_string_lossy().encode_utf16().chain(Some(0)).collect::<Vec<_>>();
 view.with_webview(move|platform|{let result=(||->windows::core::Result<()>{let environment:ICoreWebView2Environment6=platform.environment().cast()?;let settings=unsafe{environment.CreatePrintSettings()}?;unsafe{settings.SetShouldPrintBackgrounds(true)?;settings.SetShouldPrintHeaderAndFooter(false)?;settings.SetMarginTop(0.0)?;settings.SetMarginBottom(0.0)?;settings.SetMarginLeft(0.0)?;settings.SetMarginRight(0.0)?;settings.SetPageWidth(if media{11.6929133858}else{8.2677165354})?;settings.SetPageHeight(if media{6.5772440945}else{11.6929133858})?;let core:ICoreWebView2_7=platform.controller().CoreWebView2()?.cast()?;let callback=PrintToPdfCompletedHandler::create(Box::new(move|result,success|{let answer=result.map_err(|e|e.to_string()).and_then(|_|if success{Ok(())}else{Err("WebView2 could not print the PDF".into())});let _=sender.send(answer);Ok(())}));core.PrintToPdf(PCWSTR(path.as_ptr()),&settings,&callback)?;}Ok(())})();if let Err(error)=result{eprintln!("PDF print initialization: {error}");}}).map_err(|e|e.to_string())?;
 tokio::time::timeout(Duration::from_secs(90),receiver).await.map_err(|_|"PDF printing timed out")?.map_err(|_|"PDF printer was unavailable")?
}
